schemaSql:
CREATE TABLE campaigns (
  id INTEGER PRIMARY KEY,
  name TEXT,
  channel TEXT,
  daily_budget REAL
);
CREATE TABLE events (
  id INTEGER PRIMARY KEY,
  campaign_id INTEGER,
  user_id INTEGER,
  event_type TEXT,
  occurred_at TEXT
);

